window.SUNNY_DATA_READY=(async()=>{
 const compressed=Uint8Array.from(atob(""),c=>c.charCodeAt(0));
 const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));
 const data=JSON.parse(await new Response(stream).text());
 const maps=Object.fromEntries(['entities','relationships','views'].map(kind=>[kind,new Map(data.graph[kind].map(row=>[row.id,row]))]));
 for(const unit of Object.values(data.modules))for(const kind of Object.keys(maps))if(Array.isArray(unit[kind]))unit[kind]=unit[kind].map(row=>{
  const ref=row?.__sunny_graph_ref__;if(!ref)return row;
  const original=maps[ref[0]]?.get(ref[1]);if(!original)throw new Error('Unresolved SUNNY graph reference '+ref[1]);return original;
 });
 window.SUNNY_DELIVERY=data;
 window.SUNNY_INDIAN_HIERARCHY=window.SUNNY_DELIVERY.modules["indian-hierarchy"];
window.SUNNY_WESTERN_EXPANDED=window.SUNNY_DELIVERY.modules["western-expanded"];
window.SUNNY_CHINESE_EXPANDED=window.SUNNY_DELIVERY.modules["chinese-expanded"];
window.SUNNY_NATIVE_CLASSES=window.SUNNY_DELIVERY.modules["native-class-constructors"];
window.SUNNY_BIBLICAL_GENEALOGIES=window.SUNNY_DELIVERY.modules["biblical-genealogies"];
window.SUNNY_UPPER_COLOR=window.SUNNY_DELIVERY.modules["upper-legion-color-constraints"];

 return data;
})();
